def linear_command(features, weights, bias):
    if len(features) != 2 or len(weights) != 2:
        raise ValueError("Exactly two features and weights are required")
    score = features[0] * weights[0] + features[1] * weights[1] + bias
    return [score, "right" if score > 0 else "left"]

print(linear_command([4, 9], [3, 0.5], -12))

def accuracy(trials, weights, bias):
    if not trials or len(weights) != 2:
        raise ValueError("Trials and two weights are required")
    correct = 0
    for a, b, label in trials:
        score = a * weights[0] + b * weights[1] + bias
        prediction = "right" if score > 0 else "left"
        correct += prediction == label
    return correct / len(trials)

test = [[3, 8, "right"], [9, 2, "left"], [4, 7, "right"], [8, 3, "left"]]
print(accuracy(test, [-1, 1], 0))

